import numpy as np
from scipy.optimize import least_squares
def mk(model):
    def r(p):
        return model(p)-sigma
    return r
def m1(p):
    base=p[0]+p[1]*T+p[2]/T+p[3]*np.sqrt(T)
    g=np.abs(eps)**p[4]
    return base+(p[5]+p[6]*T+p[7]/T)*g
def m2(p):
    base=p[0]+p[1]*T+p[2]/T+p[3]*np.sqrt(T)
    return base+(p[4]+p[5]*T+p[6]/T)*eps+(p[7]+p[8]*T)*eps**2+(p[9])*eps**3*np.exp(p[10]*T)
